module robotic_arm #(\n    parameter N = 8,\n    parameter DATA_WIDTH = 32,\n    parameter FRACT_WIDTH = 16,\n    parameter MAX_CYCLES = 256\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire signed [DATA_WIDTH-1:0] target_x,\n    input wire signed [DATA_WIDTH-1:0] target_y,\n    input wire [DATA_WIDTH-1:0] segment_lengths [0:N-1],\n    output reg signed [DATA_WIDTH-1:0] x_coords [0:N-1],\n    output reg signed [DATA_WIDTH-1:0] y_coords [0:N-1],\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE = 3'b000;\n    localparam [2:0] CALC_SUM = 3'b001;\n    localparam [2:0] CALC_DIST = 3'b010;\n    localparam [2:0] CALC_DIR = 3'b011;\n    localparam [2:0] COMPUTE_POS = 3'b100;\n    localparam [2:0] FINISHED = 3'b101;\n\n    reg [2:0] state, next_state;\n    reg [7:0] idx, next_idx;\n    reg signed [DATA_WIDTH-1:0] sum_lengths, next_sum_lengths;\n    reg signed [DATA_WIDTH-1:0] target_dist, next_target_dist;\n    reg signed [DATA_WIDTH-1:0] angle_sin, next_angle_sin;\n    reg signed [DATA_WIDTH-1:0] angle_cos, next_angle_cos;\n    reg signed [DATA_WIDTH-1:0] acc_x, next_acc_x;\n    reg signed [DATA_WIDTH-1:0] acc_y, next_acc_y;\n    reg signed [DATA_WIDTH-1:0] scale_factor, next_scale_factor;\n    reg [7:0] cycle_count, next_cycle_count;\n\n    // Helper signals for absolute value calculation\n    wire signed [DATA_WIDTH-1:0] abs_target_x = target_x >= $signed(0) ? target_x : -target_x;\n    wire signed [DATA_WIDTH-1:0] abs_target_y = target_y >= $signed(0) ? target_y : -target_y;\n\n    always @(*) begin\n        next_state = state;\n        next_idx = idx;\n        next_sum_lengths = sum_lengths;\n        next_target_dist = target_dist;\n        next_angle_sin = angle_sin;\n        next_angle_cos = angle_cos;\n        next_acc_x = acc_x;\n        next_acc_y = acc_y;\n        next_scale_factor = scale_factor;\n        next_cycle_count = cycle_count;\n        done = 1'b0;\n\n        case (state)\n            IDLE: begin\n                if (start) begin\n                    next_state = CALC_SUM;\n                    next_idx = 8'd0;\n                    next_sum_lengths = 32'd0;\n                    next_cycle_count = 8'd0;\n                end\n            end\n\n            CALC_SUM: begin\n                if (idx < N) begin\n                    next_sum_lengths = sum_lengths + segment_lengths[idx];\n                    next_idx = idx + 8'd1;\n                end else begin\n                    next_state = CALC_DIST;\n                    next_idx = 8'd0;\n                    next_cycle_count = 8'd0;\n                end\n            end\n\n            CALC_DIST: begin\n                case (cycle_count)\n                    8'd0: begin\n                        next_target_dist = (abs_target_x + abs_target_y) >>> 1;\n                        next_cycle_count = cycle_count + 8'd1;\n                    end\n                    8'd1: begin\n                        if (target_dist <= sum_lengths) begin\n                            next_state = CALC_DIR;\n                            next_scale_factor = target_dist;\n                        end else begin\n                            next_angle_cos = target_x;\n                            next_angle_sin = target_y;\n                            next_state = COMPUTE_POS;\n                        end\n                        next_cycle_count = 8'd0;\n                        next_idx = 8'd0;\n                    end\n                    default: next_cycle_count = cycle_count + 8'd1;\n                endcase\n            end\n\n            CALC_DIR: begin\n                case (cycle_count)\n                    8'd0: begin\n                        // Approximation: scale = (2 * target_dist) / sum_lengths\n                        next_scale_factor = (target_dist << 1) / (sum_lengths >> FRACT_WIDTH);\n                        next_cycle_count = cycle_count + 8'd1;\n                    end\n                    8'd1: begin\n                        next_angle_cos = (target_x << 1) / (target_dist + 32'd1);\n                        next_angle_sin = (target_y << 1) / (target_dist + 32'd1);\n                        next_cycle_count = 8'd0;\n                        next_state = COMPUTE_POS;\n                    end\n                    default: next_cycle_count = cycle_count + 8'd1;\n                endcase\n            end\n\n            COMPUTE_POS: begin\n                if (idx < N) begin\n                    // Calculate segment delta\n                    reg signed [DATA_WIDTH-1:0] seg_len, delta_x, delta_y;\n\n                    if (target_dist <= sum_lengths) begin\n                        seg_len = (segment_lengths[idx] * scale_factor) >> FRACT_WIDTH;\n                    end else begin\n                        seg_len = segment_lengths[idx];\n                    end\n\n                    delta_x = (seg_len * angle_cos) >>> FRACT_WIDTH;\n                    delta_y = (seg_len * angle_sin) >>> FRACT_WIDTH;\n\n                    next_acc_x = acc_x + delta_x;\n                    next_acc_y = acc_y + delta_y;\n\n                    x_coords[idx] = next_acc_x;\n                    y_coords[idx] = next_acc_y;\n\n                    next_idx = idx + 8'd1;\n                end else begin\n                    next_state = FINISHED;\n                end\n            end\n\n            FINISHED: begin\n                done = 1'b1;\n                if (!start) begin\n                    next_state = IDLE;\n                end\n            end\n\n            default: next_state = IDLE;\n        endcase\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        integer i;\n        if (!rst_n) begin\n            state <= IDLE;\n            idx <= 8'd0;\n            sum_lengths <= $signed(32'd0);\n            target_dist <= $signed(32'd0);\n            angle_sin <= $signed(32'd0);\n            angle_cos <= $signed(32'd0);\n            acc_x <= $signed(32'd0);\n            acc_y <= $signed(32'd0);\n            scale_factor <= $signed(32'd0);\n            cycle_count <= 8'd0;\n            done <= 1'b0;\n\n            for (i = 0; i < N; i = i + 1) begin\n                x_coords[i] <= $signed(32'd0);\n                y_coords[i] <= $signed(32'd0);\n            end\n        end else begin\n            state <= next_state;\n            idx <= next_idx;\n            sum_lengths <= next_sum_lengths;\n            target_dist <= next_target_dist;\n            angle_sin <= next_angle_sin;\n            angle_cos <= next_angle_cos;\n            acc_x <= next_acc_x;\n            acc_y <= next_acc_y;\n            scale_factor <= next_scale_factor;\n            cycle_count <= next_cycle_count;\n            done <= (next_state == FINISHED) ? 1'b1 : 1'b0;\n        end\n    end\nendmodule